
function ptCloudOut = nextmove_processPointCloud(ptCloudIn)
% processPointCloud Process the point cloud
% ptCloudOut = processPointCloud(ptCloudIn) preprocesses the input point
% cloud ptCloudIn and returns the output point cloud ptCloudOut.

% Auto-generated by Lidar Viewer app on 2026-05-25 01:18:03

% Crop in
insideIndices = findPointsInROI(ptCloudIn, ...
    [-20 20 -40 40 -2 5 ]);
ptCloudOut = ptCloudIn.select(insideIndices,"OutputSize","full");

% Crop out
insideIndices = findPointsInROI(ptCloudOut, ...
    [0.372226 1.32542 0.712396 2.09632 -1.9 1.20771 ]);
outsideIndices = 1:ptCloudOut.Count;
outsideIndices(insideIndices) = [];
ptCloudOut = ptCloudOut.select(outsideIndices,"OutputSize","full");

% Downsample
ptCloudOut = pcdownsample(ptCloudOut,"gridAverage",0.1,PreserveStructure=true);

% Denoise by removing outlier points
ptCloudOut = pcdenoise(ptCloudOut,NumNeighbors=6,Threshold=1,PreserveStructure=true);

% Remove ground points
[~, ptCloudOut,~] = segmentGroundSMRF(ptCloudOut,1,MaxWindowRadius=12,ElevationThreshold=0.2, ...
    SlopeThreshold=0.15,ElevationScale=1.25);

end